import { useState, type KeyboardEvent } from 'react';
import { JxChip, JxInputField } from '@jinx-ui/react';

export interface ArticleTagsPickerProps {
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
  label?: string;
  placeholder?: string;
}

// JxTagInput рисует чипы внутри самого поля, а здесь они нужны отдельным списком под ним.
export default function ArticleTagsPicker({
  value,
  defaultValue = [],
  onChange,
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
}: ArticleTagsPickerProps) {
  const [draft, setDraft] = useState('');
  const [uncontrolledTags, setUncontrolledTags] = useState<string[]>(defaultValue);
  const [error, setError] = useState<string | undefined>(undefined);

  const tags = value ?? uncontrolledTags;

  const commit = (next: string[]) => {
    if (value === undefined) setUncontrolledTags(next);
    onChange?.(next);
  };

  const addTag = () => {
    const tag = draft.trim().replace(/\s+/g, ' ');
    if (tag.length === 0) return;
    if (tags.some((item) => item.toLowerCase() === tag.toLowerCase())) {
      setError(`Тег «${tag}» уже добавлен`);
      return;
    }
    setError(undefined);
    setDraft('');
    commit([...tags, tag]);
  };

  const removeTag = (index: number) => {
    setError(undefined);
    commit(tags.filter((_, position) => position !== index));
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag();
      return;
    }
    if (event.key === 'Backspace' && draft.length === 0 && tags.length > 0) {
      event.preventDefault();
      removeTag(tags.length - 1);
    }
  };

  return (
    <div style={{ display: 'grid', gap: '12px' }}>
      <JxInputField
        label={label}
        placeholder={placeholder}
        value={draft}
        onChange={(event) => {
          setDraft(event.target.value);
          setError(undefined);
        }}
        onKeyDown={handleKeyDown}
        errorText={error}
        helperText={error ? undefined : 'Enter или запятая добавляет тег, Backspace удаляет последний'}
      />

      <div
        aria-live="polite"
        style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', alignItems: 'center' }}
      >
        {tags.length === 0 ? (
          <span style={{ color: 'var(--jx-text-2)', fontFamily: 'var(--jx-font-sans)' }}>
            Тегов пока нет — введите первый и нажмите Enter
          </span>
        ) : (
          tags.map((tag, index) => (
            <JxChip key={tag} removable onRemove={() => removeTag(index)}>
              {tag}
            </JxChip>
          ))
        )}
      </div>
    </div>
  );
}

